/* ─── Tool definitions ─── */

const TOOLS: {
  type: ToolType;
  hotkey: string;
  Icon: () => JSX.Element;
}[] = [
  { type: 'select',    hotkey: 'V', Icon: IconMove },
  { type: 'star',      hotkey: 'S', Icon: IconStar },
  { type: 'ellipse',   hotkey: 'O', Icon: IconEllipse },
  { type: 'rectangle', hotkey: 'R', Icon: IconRect },
  { type: 'freehand',  hotkey: 'F', Icon: IconFreehand },
];

const ARC_MODES = [
  { mode: 'full'    as const, icon: '◯', label: 'Полный эллипс' },
  { mode: 'half'    as const, icon: '⌓', label: 'Полудуга' },
  { mode: 'quarter' as const, icon: '◜', label: 'Четверть дуги' },
];

const PLACE_TOOLS = new Set<ToolType>(['rectangle', 'ellipse', 'star']);

function toolButtonRadius(i: number, total: number) {
  if (total === 1) return 'rounded-[16px]';
  if (i === 0) return 'rounded-tl-[16px] rounded-bl-[16px] rounded-tr-[2px] rounded-br-[2px]';
  if (i === total - 1) return 'rounded-tr-[16px] rounded-br-[16px] rounded-tl-[2px] rounded-bl-[2px]';
  return 'rounded-[2px]';
}

export function BottomBar() {
  const activeTool = useToolStore((s) => s.activeTool);
  const setActiveTool = useToolStore((s) => s.setActiveTool);
  const ellipseMode = useUIStore((s) => s.ellipseMode);
  const setEllipseMode = useUIStore((s) => s.setEllipseMode);
  const animationPlaying = useUIStore((s) => s.animationPlaying);
  const setAnimationPlaying = useUIStore((s) => s.setAnimationPlaying);
  const [hoveringEllipse, setHoveringEllipse] = useState(false);
  const ellipseHideTimer = useRef<ReturnType<typeof setTimeout> | null>(null);

  function onEllipseEnter() {
    if (ellipseHideTimer.current) clearTimeout(ellipseHideTimer.current);
    setHoveringEllipse(true);
  }
  function onEllipseLeave() {
    ellipseHideTimer.current = setTimeout(() => setHoveringEllipse(false), 150);
  }

  function placeShapeAtCenter(type: 'rectangle' | 'ellipse' | 'star') {
    const { documentWidth: dw, documentHeight: dh } = useUIStore.getState().viewport;
    const size = Math.min(dw, dh) * 0.35;
    const x = dw / 2 - size / 2;
    const y = dh / 2 - size / 2;
    const base = { id: uid(), position: { x, y }, width: size, height: size, rotation: 0, visible: true, locked: false };
    let obj: RectangleObject | EllipseObject | StarObject;
    if (type === 'rectangle') {
      obj = { ...base, type: 'rectangle' };
    } else if (type === 'ellipse') {
      obj = { ...base, type: 'ellipse', arcStartAngle: 0, arcEndAngle: Math.PI * 2 };
    } else {
      obj = { ...base, type: 'star', points: 5, innerRadiusRatio: 0.4 };
    }
    useSceneStore.getState().addObject(obj);
    useToolStore.getState().setActiveTool('select');
    useToolStore.getState().selectObjects([obj.id]);
  }

  function getToolClickHandler(type: ToolType): () => void {
    if (PLACE_TOOLS.has(type)) {
      return () => placeShapeAtCenter(type as 'rectangle' | 'ellipse' | 'star');
    }
    return () => setActiveTool(type);
  }

  return (
    <div className="flex items-center justify-center h-[68px] bg-black px-4 shrink-0">
      <div className="flex items-center gap-2">
        {/* Centered tools pill */}
        <div className="bg-[#0e0f11] rounded-[22px] px-[6px] py-[6px] flex gap-[2px]">
          {TOOLS.map((tool, i) =>
            tool.type === 'ellipse' ? (
              <div
                key="ellipse"
                className="relative"
                onMouseEnter={onEllipseEnter}
                onMouseLeave={onEllipseLeave}
              >
                {(activeTool === 'ellipse' || hoveringEllipse) && (
                  <div
                    className="absolute bottom-full mb-2 left-1/2 -translate-x-1/2 flex items-center gap-[2px] bg-[#0e0f11] rounded-[14px] px-[6px] py-[6px]"
                    onMouseEnter={onEllipseEnter}
                    onMouseLeave={onEllipseLeave}
                  >
                    {ARC_MODES.map(({ mode, icon, label }) => (
                      <button
                        key={mode}
                        onClick={() => setEllipseMode(mode)}
                        title={label}
                        className={[
                          'px-2 py-1 rounded-[8px] text-base transition-colors',
                          ellipseMode === mode
                            ? 'bg-[#33373f] text-white'
                            : 'text-[#777e8c] hover:bg-[#1a1d21]',
                        ].join(' ')}
                      >
                        {icon}
                      </button>
                    ))}
                    <span className="text-[10px] text-[#454a55] ml-1 font-mono">⌥O</span>
                  </div>
                )}
                <button
                  onClick={getToolClickHandler(tool.type)}
                  className={[
                    'flex flex-col items-center justify-center gap-1 h-[44px] px-2 transition-colors',
                    toolButtonRadius(i, TOOLS.length),
                    activeTool === tool.type
                      ? 'bg-[#33373f] text-white'
                      : 'text-[#777e8c] hover:bg-[#1a1d21]',
                  ].join(' ')}
                >
                  <tool.Icon />
                  <span className="font-cond-regular text-[10px] leading-none">{tool.hotkey}</span>
                </button>
              </div>
            ) : (
              <button
                key={tool.type}
                onClick={getToolClickHandler(tool.type)}
                className={[
                  'flex flex-col items-center justify-center gap-1 h-[44px] px-2 transition-colors',
                  toolButtonRadius(i, TOOLS.length),
                  activeTool === tool.type
                    ? 'bg-[#33373f] text-white'
                    : 'text-[#777e8c] hover:bg-[#1a1d21]',
                ].join(' ')}
              >
                <tool.Icon />
                <span className="font-cond-regular text-[10px] leading-none">{tool.hotkey}</span>
              </button>
            )
          )}
        </div>

        <button
          onClick={() => setAnimationPlaying(!animationPlaying)}
          title={animationPlaying ? 'Пауза (Space)' : 'Запустить (Space)'}
          className="flex items-center gap-2 px-1 py-2 rounded-[4px] font-cond-regular text-[18px] text-[#777e8c] hover:text-white transition-colors"
        >
          {animationPlaying ? <PauseIcon /> : <PlayIcon />}
          {animationPlaying ? 'Пауза' : 'Запустить'}
        </button>
      </div>
    </div>
  );
}
